<?php foreach (['nombres'=>'Nombres','apellidos'=>'Apellidos','email'=>'Correo de acceso','telefono'=>'Teléfono'] as $key=>$label): ?><div class="col-md-6"><label class="form-label" for="<?= e($key) ?>"><?= e($label) ?><?= $key!=='telefono' ? ' *' : '' ?></label><input class="form-control" id="<?= e($key) ?>" name="<?= e($key) ?>" type="<?= $key==='email' ? 'email' : ($key==='telefono' ? 'tel' : 'text') ?>" maxlength="<?= $key==='email' ? 120 : ($key==='telefono' ? 20 : 80) ?>" <?= $key!=='telefono' ? 'required' : '' ?> value="<?= e($account[$key] ?? '') ?>"></div><?php endforeach; ?>
